package com.hiro.ulike;import java.util.*;public class ManualLens170{static final Map<String,Object>f=new HashMap<>();private static final Map<Object,Object>PINNED=new WeakHashMap<>(),SESSION_TOKENS=new WeakHashMap<>(),CURRENT_SESSIONS=new WeakHashMap<>();static void put(String n,Object o)throws ReflectiveOperationException{f.put(n,o);}static Object get(String s)throws ReflectiveOperationException{return f.get(s);}static long number(String s)throws ReflectiveOperationException{return ((Number)get(s)).longValue();}static boolean yes(String s)throws ReflectiveOperationException{return Boolean.TRUE.equals(get(s));}static void setup(Object r,long t){SESSION_TOKENS.put(r,t);}static void pin(Object s,Object r){PINNED.put(s,r);CURRENT_SESSIONS.put(r,new java.lang.ref.WeakReference<>(s));}static Object session(Object r){return CURRENT_SESSIONS.get(r);}static void reset(){f.clear();PINNED.clear();SESSION_TOKENS.clear();CURRENT_SESSIONS.clear();}}
